#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> raw_a(n);
    for (int i = 0; i < n; ++i) {
        cin >> raw_a[i];
    }

    // Adiciona borda 0 no início
    vector<int> a;
    a.push_back(0);

    // Remove duplicatas consecutivas
    for (int i = 0; i < n; ++i) {
        if (a.empty() || a.back() != raw_a[i]) {
            a.push_back(raw_a[i]);
        }
    }
    // Adiciona borda 0 no fim
    a.push_back(0);

    int m = a.size();
    // Índices de 1 a m - 2 são os retângulos originais comprimidos
    vector<int> p(m - 2);
    for (int i = 0; i < m - 2; ++i) {
        p[i] = i + 1;
    }

    // Ordena os índices por altura em ordem decrescente
    sort(p.begin(), p.end(), [&](int i, int j) {
        return a[i] > a[j];
    });

    int current_components = 0;
    int max_components = 0;

    int i = 0;
    int total_elements = p.size();
    while (i < total_elements) {
        int j = i;
        int current_height = a[p[i]];

        // Processa todos os elementos com a mesma altura
        while (j < total_elements && a[p[j]] == current_height) {
            int idx = p[j];
            bool left_lower = a[idx - 1] < a[idx];
            bool right_lower = a[idx + 1] < a[idx];
            bool left_higher = a[idx - 1] > a[idx];
            bool right_higher = a[idx + 1] > a[idx];

            if (left_lower && right_lower) {
                // Pico local: surge uma nova componente
                current_components++;
            } else if (left_higher && right_higher) {
                // Vale local: duas componentes se unem
                current_components--;
            }
            j++;
        }

        // Atualiza a resposta para a linha de corte logo abaixo de current_height
        max_components = max(max_components, current_components);
        i = j;
    }

    // O total de pedaços é a base (1 pedaço) + número de componentes acima do corte
    cout << 1 + max_components << "\n";

    return 0;
}
